def render_figure(self: Any, text: str, align: Optional[str] = None, figwidth: Optional[str] = None, figclass: Optional[str] = None) -> str:
    attrs = ''
    if align:
        attrs += ' align="' + align + '"'
    if figwidth:
        attrs += ' style="width:' + escape_text(figwidth) + '"'
    if figclass:
        attrs += ' class="' + escape_text(figclass) + '"'
    return '<figure' + attrs + '>\n' + text + '</figure>\n'
